/* SQL Server: open this file in SSMS and press F5. Nothing else is needed.
   The script creates the FoodRush database if missing, switches to it,
   and rebuilds all tables (re-running it resets the data). */
IF DB_ID('FoodRush') IS NULL CREATE DATABASE FoodRush;
GO
USE FoodRush;
GO

/* =====================================================================
   FoodRush: food delivery platform database (teaching database)
   13 tables, replacing Northwind for an introductory SQL course.
   Target: SQL Server 2016+ (SSMS). Also runs on SQLite/PostgreSQL without the first lines.
   Booleans are stored as 0/1 (SMALLINT). Dates are DATE, times are TIME(0).
   Built-in teaching traps:
     - NULLs: orders.courier_id (pickup/cancelled), orders.coupon_id, orders.tip,
       reviews.review_text, customers.phone, customers.referred_by, couriers.supervisor_id
     - Rows with no matches (for LEFT JOIN / NOT IN / NOT EXISTS):
       cities with no restaurants, a cuisine with no restaurants, a restaurant
       with no orders, menu items never ordered, customers who never ordered,
       a courier with no deliveries, a coupon never used
     - Self joins: customers.referred_by, couriers.supervisor_id
     - order_items.unit_price differs from current menu_items.price (price rise on 2026-01-01)
     - Order total is NOT stored: SUM(quantity*unit_price) + delivery_fee
   ===================================================================== */

DROP TABLE IF EXISTS favorites;
DROP TABLE IF EXISTS reviews;
DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS payment_methods;
DROP TABLE IF EXISTS coupons;
DROP TABLE IF EXISTS couriers;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS menu_items;
DROP TABLE IF EXISTS dish_categories;
DROP TABLE IF EXISTS restaurants;
DROP TABLE IF EXISTS cuisines;
DROP TABLE IF EXISTS cities;

CREATE TABLE cities (
    city_id      INT          NOT NULL PRIMARY KEY,
    city_name    VARCHAR(50)  NOT NULL,
    district     VARCHAR(30)  NOT NULL
);

CREATE TABLE cuisines (
    cuisine_id   INT          NOT NULL PRIMARY KEY,
    cuisine_name VARCHAR(40)  NOT NULL
);

CREATE TABLE restaurants (
    restaurant_id    INT          NOT NULL PRIMARY KEY,
    restaurant_name  VARCHAR(60)  NOT NULL,
    cuisine_id       INT          NOT NULL REFERENCES cuisines(cuisine_id),
    city_id          INT          NOT NULL REFERENCES cities(city_id),
    opened_date      DATE         NOT NULL,
    is_kosher        SMALLINT     NOT NULL,   -- 1 = kosher
    avg_prep_minutes INT          NOT NULL
);

CREATE TABLE dish_categories (
    category_id   INT          NOT NULL PRIMARY KEY,
    category_name VARCHAR(30)  NOT NULL
);

CREATE TABLE menu_items (
    item_id       INT           NOT NULL PRIMARY KEY,
    restaurant_id INT           NOT NULL REFERENCES restaurants(restaurant_id),
    category_id   INT           NOT NULL REFERENCES dish_categories(category_id),
    item_name     VARCHAR(60)   NOT NULL,
    price         DECIMAL(8,2)  NOT NULL,     -- current price
    is_vegan      SMALLINT      NOT NULL,
    is_available  SMALLINT      NOT NULL
);

CREATE TABLE customers (
    customer_id  INT          NOT NULL PRIMARY KEY,
    first_name   VARCHAR(30)  NOT NULL,
    last_name    VARCHAR(30)  NOT NULL,
    city_id      INT          NOT NULL REFERENCES cities(city_id),
    birth_date   DATE         NOT NULL,
    join_date    DATE         NOT NULL,
    email        VARCHAR(80)  NOT NULL,
    phone        VARCHAR(15),
    referred_by  INT          REFERENCES customers(customer_id)
);

CREATE TABLE couriers (
    courier_id    INT          NOT NULL PRIMARY KEY,
    first_name    VARCHAR(30)  NOT NULL,
    last_name     VARCHAR(30)  NOT NULL,
    city_id       INT          NOT NULL REFERENCES cities(city_id),
    vehicle_type  VARCHAR(15)  NOT NULL,
    hire_date     DATE         NOT NULL,
    supervisor_id INT          REFERENCES couriers(courier_id)
);

CREATE TABLE coupons (
    coupon_id    INT          NOT NULL PRIMARY KEY,
    coupon_code  VARCHAR(20)  NOT NULL,
    discount_pct INT          NOT NULL,
    valid_from   DATE         NOT NULL,
    valid_to     DATE         NOT NULL
);

CREATE TABLE payment_methods (
    payment_method_id INT          NOT NULL PRIMARY KEY,
    method_name       VARCHAR(20)  NOT NULL
);

CREATE TABLE orders (
    order_id          INT           NOT NULL PRIMARY KEY,
    customer_id       INT           NOT NULL REFERENCES customers(customer_id),
    restaurant_id     INT           NOT NULL REFERENCES restaurants(restaurant_id),
    courier_id        INT           REFERENCES couriers(courier_id),    -- NULL = pickup / cancelled
    payment_method_id INT           NOT NULL REFERENCES payment_methods(payment_method_id),
    coupon_id         INT           REFERENCES coupons(coupon_id),
    order_date        DATE          NOT NULL,
    order_time        TIME(0)       NOT NULL,   -- TIME(0): shows 19:46:00, no fractions
    order_status      VARCHAR(15)   NOT NULL,  -- Delivered / Picked Up / Cancelled
    delivery_fee      DECIMAL(6,2)  NOT NULL,
    tip               DECIMAL(6,2),            -- NULL = not delivered, 0 = no tip
    delivery_minutes  INT                      -- NULL = not delivered
);

CREATE TABLE order_items (
    order_id   INT           NOT NULL REFERENCES orders(order_id),
    item_id    INT           NOT NULL REFERENCES menu_items(item_id),
    quantity   INT           NOT NULL,
    unit_price DECIMAL(8,2)  NOT NULL,          -- price at time of order
    PRIMARY KEY (order_id, item_id)
);

CREATE TABLE reviews (
    review_id   INT           NOT NULL PRIMARY KEY,
    order_id    INT           NOT NULL REFERENCES orders(order_id),
    rating      INT           NOT NULL,         -- 1..5
    review_text VARCHAR(200),
    review_date DATE          NOT NULL
);

CREATE TABLE favorites (
    customer_id   INT   NOT NULL REFERENCES customers(customer_id),
    restaurant_id INT   NOT NULL REFERENCES restaurants(restaurant_id),
    added_date    DATE  NOT NULL,
    PRIMARY KEY (customer_id, restaurant_id)
);

